#!/usr/bin/env node
// Generates every AI tool's config from the single source of truth in ai/ (+ AGENTS.md). Zero dependencies.
//   node scripts/ai/sync.mjs          write/refresh generated files (removes stale generated files)
//   node scripts/ai/sync.mjs --check  CI mode: fail if anything is out of date or over its token budget
import { readFileSync, writeFileSync, mkdirSync, existsSync, readdirSync, rmSync, statSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';

const ROOT = process.cwd();
const CHECK = process.argv.includes('--check');
const read = (p) => readFileSync(join(ROOT, p), 'utf8');
const manifest = JSON.parse(read('ai/manifest.json'));
const tokens = (s) => Math.ceil(s.length / 4); // rough, model-agnostic estimate
const BANNER = (src) => `<!-- GENERATED by scripts/ai/sync.mjs from ${src}. Do not edit: change the source, then run \`npm run ai:sync\`. -->`;
const HASH_BANNER = (src) => `# GENERATED by scripts/ai/sync.mjs from ${src}. Do not edit: change the source, then run \`npm run ai:sync\`.`;
const MARK = 'GENERATED by scripts/ai/sync.mjs';
const yamlList = (xs) => `[${xs.map((x) => JSON.stringify(x)).join(', ')}]`;

const rules = manifest.rules.map((r) => ({ ...r, body: read(r.file).trim() }));
const playbooks = manifest.playbooks.map((p) => ({ ...p, file: `ai/playbooks/${p.id}.md`, body: read(`ai/playbooks/${p.id}.md`).trim() }));
const agents = read('AGENTS.md');
const ignore = read('ai/ignore').split('\n').filter((l) => l.trim() && !l.startsWith('#'));

// ---------- repo map: path → purpose (line 1 of every source file) ----------
function walk(dir) {
  if (!existsSync(join(ROOT, dir))) return [];
  return readdirSync(join(ROOT, dir)).flatMap((n) => {
    const p = join(dir, n);
    if (n === 'node_modules' || n.startsWith('.')) return [];
    return statSync(join(ROOT, p)).isDirectory() ? walk(p) : /\.(ts|mjs)$/.test(n) ? [p] : [];
  });
}
function purpose(file) {
  const lines = read(file).split('\n');
  const line = lines[0].startsWith('#!') ? lines[1] : lines[0];
  const m = line.match(/^\s*(?:\/\*\*|\/\/)\s*(.*?)\s*(?:\*\/)?$/);
  return m ? m[1] : null;
}
const sourceFiles = ['src', 'tests', 'config', 'scripts', 'demo-app'].flatMap(walk).sort();
const missingPurpose = sourceFiles.filter((f) => !purpose(f));
const byDir = {};
for (const f of sourceFiles) (byDir[dirname(f)] ??= []).push(`- \`${f}\`: ${purpose(f) ?? '(no purpose line)'}`);
const repoMap = [
  '# Repository map', '', BANNER('line 1 of each source file'), '',
  'One line per file. Read this instead of opening files to find where something lives.', '',
  ...Object.entries(byDir).flatMap(([d, items]) => [`## ${d}/`, ...items, '']),
  '## config/environments/', ...readdirSync(join(ROOT, 'config/environments')).map((f) => `- \`config/environments/${f}\`: environment definition (validated by src/config/env.schema.ts)`), '',
].join('\n');

const playbookIndex = playbooks.map((p) => `- \`${p.file}\`: ${p.description}`).join('\n');
const ruleIndex = rules.map((r) => `- \`${r.file}\` (${r.globs.join(', ')}): ${r.description}`).join('\n');

// ---------- outputs ----------
const out = new Map();
const put = (path, content) => out.set(path, content.endsWith('\n') ? content : content + '\n');

put('ai/context/repo-map.md', repoMap);

// Claude Code
put('CLAUDE.md', [`# CLAUDE.md`, '', BANNER('ai/ + AGENTS.md'), '', '@AGENTS.md', '',
  '## Claude Code specifics',
  '- Path-scoped rules load automatically from `.claude/rules/` when you touch matching files.',
  `- Skills (also \`/name\` commands): ${playbooks.map((p) => `\`/${p.id}\``).join(', ')}.`,
  '- MCP: `playwright-test` (from `.mcp.json`) runs/debugs tests with this repo\'s config: prefer `browser_snapshot` over guessing selectors.',
  '- Repository map: `ai/context/repo-map.md`. Glossary: `ai/context/glossary.md`.'].join('\n'));
for (const r of rules) put(`.claude/rules/${r.id}.md`, `---\npaths: ${yamlList(r.globs)}\n---\n${BANNER(r.file)}\n\n${r.body}`);
for (const p of playbooks) put(`.claude/skills/${p.id}/SKILL.md`, `---\nname: ${p.id}\ndescription: ${p.description}. Use when asked to ${p.description.charAt(0).toLowerCase() + p.description.slice(1)}.\n---\n${BANNER(p.file)}\n\n${p.body}`);
put('.claude/settings.json', JSON.stringify({
  permissions: {
    allow: ['Bash(npm run verify)', 'Bash(npm run typecheck)', 'Bash(npm run lint:locators)', 'Bash(npm run ai:check)', 'Bash(npm run health)', 'Bash(npx playwright test *)', 'Bash(git diff *)', 'Bash(git status *)'],
    deny: ['Read(./.env)', 'Read(./.env.*)', 'Read(./.secrets/**)', 'Edit(./.env)', 'Edit(./.secrets/**)', 'Bash(git push *)'],
  },
}, null, 2));
put('.mcp.json', JSON.stringify({ mcpServers: { 'playwright-test': { command: 'npx', args: ['playwright', 'run-test-mcp-server'] } } }, null, 2));

// GitHub Copilot (VS Code + coding agent)
put('.github/copilot-instructions.md', [BANNER('ai/ + AGENTS.md'), '', '# Copilot instructions', '',
  'The project rules are in `/AGENTS.md`: follow them. Path-specific rules are in `.github/instructions/`; task playbooks are prompt files in `.github/prompts/` (run them with `/name` in chat).', '',
  'Most important: selectors only in `src/ui/**/*.locators.ts`; specs import `{ test, expect }` from `src/fixtures`; parameterized SQL and the `soql` template; zod schemas for API responses and test data; never weaken assertions to make a test pass; run `npm run verify` before proposing a change.', '',
  'Repository map: `ai/context/repo-map.md`.'].join('\n'));
for (const r of rules) put(`.github/instructions/${r.id}.instructions.md`, `---\napplyTo: "${r.globs.join(',')}"\n---\n${BANNER(r.file)}\n\n${r.body}`);
for (const p of playbooks) put(`.github/prompts/${p.id}.prompt.md`, `---\ndescription: "${p.description}"\n---\n${BANNER(p.file)}\n\nFollow /AGENTS.md and this playbook for the task described by the user.\n\n${p.body}`);

// Gemini CLI
put('GEMINI.md', [`# GEMINI.md`, '', BANNER('ai/'), '',
  '`AGENTS.md` is loaded too (see `.gemini/settings.json` → `context.fileName`). This file only adds Gemini-specific pointers.', '',
  '## Scoped rules: read the matching file before editing', ruleIndex, '',
  '## Playbooks (also available as `/` commands from `.gemini/commands/`)', playbookIndex, '',
  '## Context', '@./ai/context/glossary.md'].join('\n'));
put('.gemini/settings.json', JSON.stringify({ context: { fileName: ['AGENTS.md', 'GEMINI.md'] } }, null, 2));
for (const p of playbooks) put(`.gemini/commands/${p.id}.toml`, `${HASH_BANNER(p.file)}\ndescription = ${JSON.stringify(p.description)}\nprompt = """\nFollow AGENTS.md and the playbook below.\n\nTask: {{args}}\n\n${p.body.replace(/"""/g, '\\"\\"\\"')}\n"""`);
put('.geminiignore', `${HASH_BANNER('ai/ignore')}\n${ignore.join('\n')}`);

// Cursor
for (const r of rules) put(`.cursor/rules/${r.id}.mdc`, `---\ndescription: ${r.description}\nglobs: ${r.globs.join(',')}\nalwaysApply: false\n---\n${BANNER(r.file)}\n\n${r.body}`);
put('.cursorignore', `${HASH_BANNER('ai/ignore')}\n${ignore.join('\n')}`);

// Continue (VS Code / JetBrains; typical front end for local Llama/Qwen models via Ollama). Reads AGENTS.md natively.
for (const r of rules) put(`.continue/rules/${r.id}.md`, `---\nname: ${r.id}\ndescription: ${r.description}\nglobs: ${yamlList(r.globs)}\nalwaysApply: false\n---\n${BANNER(r.file)}\n\n${r.body}`);

// Cline (also used with local models): always-on project rules + an index of on-demand files.
put('.clinerules/00-project.md', `${BANNER('AGENTS.md')}\n\n${agents.trim()}`);
put('.clinerules/01-index.md', [BANNER('ai/manifest.json'), '', '# On-demand context (read only what the task needs)', '', '## Scoped rules', ruleIndex, '', '## Playbooks', playbookIndex, '', '## Maps', '- `ai/context/repo-map.md`: where everything lives', '- `ai/context/glossary.md`: domain terms'].join('\n'));

// Aider (works with any model incl. local ones via Ollama)
put('.aider.conf.yml', `${HASH_BANNER('ai/')}\n# Always-loaded, read-only context. Kept small on purpose for local models.\nread: [AGENTS.md, ai/context/glossary.md]\n`);
put('.aiderignore', `${HASH_BANNER('ai/ignore')}\n${ignore.join('\n')}`);

// Any LLM / chat UI: llms.txt index (llmstxt.org convention)
put('llms.txt', ['# playwright-e2e-test', '', '> Multi-tenant Playwright + TypeScript test framework: UI (page objects, components, self-healing locators), API, PostgreSQL, Salesforce SOQL, multi-source test data, file validation, device matrix.', '',
  '## Start here', '- [AGENTS.md](AGENTS.md): rules for AI assistants', '- [Repository map](ai/context/repo-map.md): one line per file', '- [Architecture](docs/ARCHITECTURE.md)', '- [Locator standard](docs/LOCATOR-STANDARD.md)', '',
  '## Playbooks', ...playbooks.map((p) => `- [${p.id}](${p.file}): ${p.description}`), '',
  '## Reference implementations', '- [Master showcase test](tests/showcase/master-showcase.spec.ts)', '- [Locator file](src/ui/pages/demo/login.locators.ts) and [page object](src/ui/pages/demo/login.page.ts)', '- [API test](tests/api/patients.api.spec.ts)', '',
  '## Optional', '- [Glossary](ai/context/glossary.md)', '- [AI layer](ai/README.md)', '- [Review of the previous version](docs/REVIEW.md)'].join('\n'));

// ---------- checks ----------
const problems = [];
const budget = manifest.budgets;
if (tokens(agents) > budget['AGENTS.md']) problems.push(`AGENTS.md is ~${tokens(agents)} tokens (budget ${budget['AGENTS.md']}); it is loaded in every conversation, so move detail to ai/rules or ai/playbooks.`);
for (const r of rules) if (tokens(r.body) > budget.rule) problems.push(`${r.file} is ~${tokens(r.body)} tokens (budget ${budget.rule}).`);
for (const p of playbooks) if (tokens(p.body) > budget.playbook) problems.push(`${p.file} is ~${tokens(p.body)} tokens (budget ${budget.playbook}).`);
for (const f of missingPurpose) problems.push(`${f}: first line must be a one-line purpose comment (/** … */ or // …).`);
for (const r of rules) for (const g of r.globs) if (!existsSync(join(ROOT, g.split('/**')[0].split('*')[0]))) problems.push(`${r.file}: glob ${g} matches no existing path.`);

// Stale generated files (e.g. a removed playbook) in managed folders.
const managed = ['.claude/rules', '.claude/skills', '.github/instructions', '.github/prompts', '.gemini/commands', '.cursor/rules', '.continue/rules', '.clinerules'];
const stale = managed.flatMap((d) => {
  const walkAll = (p) => !existsSync(join(ROOT, p)) ? [] : readdirSync(join(ROOT, p)).flatMap((n) => statSync(join(ROOT, p, n)).isDirectory() ? walkAll(join(p, n)) : [join(p, n)]);
  return walkAll(d).filter((f) => !out.has(f) && read(f).includes(MARK));
});

const drift = [...out].filter(([p, c]) => !existsSync(join(ROOT, p)) || read(p) !== c).map(([p]) => p);
if (CHECK) {
  for (const p of drift) problems.push(`${p} is out of date: run \`npm run ai:sync\` (never edit generated files by hand).`);
  for (const p of stale) problems.push(`${p} is a stale generated file: run \`npm run ai:sync\`.`);
  if (problems.length) { console.error(problems.join('\n')); process.exit(1); }
  console.log(`ai:check OK: ${out.size} generated files in sync; budgets OK (AGENTS.md ~${tokens(agents)} tokens).`);
} else {
  for (const p of drift) { mkdirSync(dirname(join(ROOT, p)), { recursive: true }); writeFileSync(join(ROOT, p), out.get(p)); }
  for (const p of stale) rmSync(join(ROOT, p));
  console.log(`ai:sync: ${drift.length} file(s) written, ${stale.length} stale removed, ${out.size - drift.length} unchanged.`);
  if (problems.length) { console.error(`\nWarnings:\n${problems.join('\n')}`); process.exit(1); }
}
